// One source of truth for player-facing copy. Keep keys stable: translators use
// them to discuss changes even when the English wording is revised.
//
// id/ms/zh-CN are first-pass translations and intentionally marked draft in
// the export script. Product/legal copy should be professionally reviewed
// before those locales are described as final.
const entry = (key, en, id, ms, zhCN, context = '') => Object.freeze({
  key,
  context,
  en,
  id,
  ms,
  'zh-CN': zhCN,
  status: 'draft',
})

